function isZeroArray(nums, queries) {
  // Simulate the queries: each one lowers every element of its range that is still above zero.
  const values = nums.slice();
  for (const [l, r] of queries) {
    for (let i = l; i <= r; i++) if (values[i] > 0) values[i]--;
  }
  return values.every(v => v === 0);
}

