function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 6);
  const q = large ? 2000 : 1 + Math.floor(rand() * 6);
  const short = rand() < 0.4;
  const queries = [];
  for (let j = 0; j < q; j++) {
    const a = Math.floor(rand() * n);
    const b = short ? Math.min(n - 1, a + Math.floor(rand() * 4)) : Math.floor(rand() * n);
    queries.push([Math.min(a, b), Math.max(a, b)]);
  }
  // Count how many queries cover each index and keep every value at or below that count (a true answer),
  // then half the time push one value past its count (a false answer).
  const diff = new Array(n + 1).fill(0);
  for (const [l, r] of queries) { diff[l]++; diff[r + 1]--; }
  const cover = [];
  let running = 0;
  for (let i = 0; i < n; i++) { running += diff[i]; cover.push(running); }
  const nums = cover.map(c => rand() < 0.4 ? c : Math.floor(rand() * (c + 1)));
  if (rand() < 0.5) {
    const i = Math.floor(rand() * n);
    nums[i] = cover[i] + 1 + Math.floor(rand() * 3);
  }
  return [nums, queries];
}
